-- 006: финальная программа H2 (9 циклов) + V9 (13 циклов), RMref = 115 кг
-- Старая программа скрывается (block -> archive_*), история сессий не трогается.
-- Без AMRAP и дожимов с бруска/пин-пресса; паузный жим и Spoto; проценты — от RMref 115;
-- обновление RMref — только вручную на контрольных точках (+2,5 при двух подтверждениях).

UPDATE cycles SET block = 'archive_' || block WHERE block IN ('h2','v9');

ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

