INSERT INTO app_settings(key, value) VALUES ('tm_macro1','115'), ('tm_macro2','115'), ('tm_macro3','115')
INSERT INTO cycles (number, name, macrocycle, notes, sort_order, block) VALUES (1, 'Цикл 1 — Вход', 1, 'Дни 1–2 (P1–P2) и 5–6 (P3–P4) — рабочие смены по 12 часов. Никакой силовой работы. Обычная бытовая активность; ориентир 7–9 тыс. шагов — только если не мешает восстановлению, без «добора» шагов поздними прогулками. Приоритет сна. После B2 отслеживать реакцию груди, локтей и плеч: лёгкая болезненность допустима, боль — нет.', 101, 'h2');
