INSERT INTO cycles (number, name, macrocycle, notes, sort_order, block) VALUES (9, 'Цикл 9 — Мост к силовому блоку', 1, 'Дни 1–2 и 5–6 — смены по 12 ч без силовой. Сон важнее дополнительной активности. Все веса — стартовые ориентиры: RPE последнего подхода важнее числа. После этого цикла — переход к силовому блоку V9: 4 лёгких дня и контрольная точка №1 (обновление RMref только при двух сопоставимых подтверждениях).', 109, 'h2');
